CREATE TABLE IF NOT EXISTS public."type" (
  "typeId" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  name VARCHAR(100) NOT NULL
);

CREATE TABLE IF NOT EXISTS public.menu (
  "menuId" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  name VARCHAR(150) NOT NULL,
  price NUMERIC(10, 2) NOT NULL CHECK (price >= 0),
  "isBestSeller" BOOLEAN NOT NULL DEFAULT FALSE,
  "typeId" INTEGER NOT NULL REFERENCES public."type" ("typeId")
    ON UPDATE CASCADE
    ON DELETE RESTRICT
);

CREATE INDEX IF NOT EXISTS idx_menu_type_id ON public.menu ("typeId");
